// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title ProxyAwareDBDriver
 * @notice Database driver that operates behind a reverse proxy layer
 * @dev Handles frame-origin validation for cross-origin embedding protection
 */
contract ProxyAwareDBDriver is Ownable, ReentrancyGuard {

    struct QueryResult {
        bytes32 dataHash;
        uint256 timestamp;
        address origin;
        bool validated;
    }

    struct FramePolicy {
        bytes32 allowedOriginHash;
        uint8 disposition;  // 0=DENY, 1=SAMEORIGIN, 2=ALLOW-FROM
        bool enforced;
        uint256 nonce;
    }

    mapping(address => FramePolicy) public framePolicies;
    mapping(bytes32 => QueryResult) public queryCache;
    mapping(address => uint256) public proxyNonces;

    address public reverseProxy;
    bytes32 public trustedOriginHash;
    uint256 public policyVersion;

    event PolicyUpdated(address indexed caller, uint8 disposition, uint256 version);
    event QueryExecuted(bytes32 indexed queryId, address indexed origin);
    event FrameValidation(address indexed origin, bool allowed);

    modifier onlyProxy() {
        require(msg.sender == reverseProxy || tx.origin == owner(), "Not authorized proxy");
        _;
    }

    modifier frameGuard(address origin) {
        FramePolicy memory policy = framePolicies[origin];
        if (policy.enforced) {
            require(_validateFrameDisposition(origin, policy), "Frame policy violation");
        }
        _;
    }

    constructor(address _proxy, bytes32 _trustedOrigin) {
        reverseProxy = _proxy;
        trustedOriginHash = _trustedOrigin;
        policyVersion = 1;

        // Initialize default policy - SAMEORIGIN
        framePolicies[_proxy] = FramePolicy({
            allowedOriginHash: _trustedOrigin,
            disposition: 1,
            enforced: true,
            nonce: 0
        });
    }

    function setFramePolicy(
        address target,
        uint8 disposition,
        bytes32 originHash
    ) external onlyProxy {
        require(disposition <= 2, "Invalid disposition");

        uint256 currentNonce = proxyNonces[msg.sender];

        framePolicies[target] = FramePolicy({
            allowedOriginHash: originHash,
            disposition: disposition,
            enforced: disposition != 2,  // ALLOW-FROM disables enforcement
            nonce: currentNonce + 1
        });

        proxyNonces[msg.sender] = currentNonce + 1;
        policyVersion++;

        emit PolicyUpdated(target, disposition, policyVersion);
    }

    function executeQuery(
        bytes32 queryId,
        bytes calldata queryData,
        address callerOrigin
    ) external nonReentrant onlyProxy frameGuard(callerOrigin) returns (bytes32) {

        bytes32 dataHash = keccak256(queryData);

        queryCache[queryId] = QueryResult({
            dataHash: dataHash,
            timestamp: block.timestamp,
            origin: callerOrigin,
            validated: true
        });

        emit QueryExecuted(queryId, callerOrigin);
        return dataHash;
    }

    function batchExecuteWithFrameCheck(
        bytes32[] calldata queryIds,
        bytes[] calldata queries,
        address[] calldata origins
    ) external nonReentrant onlyProxy returns (bytes32[] memory) {
        require(
            queryIds.length == queries.length && queries.length == origins.length,
            "Array length mismatch"
        );

        bytes32[] memory results = new bytes32[](queryIds.length);

        for (uint256 i = 0; i < queryIds.length; i++) {
            // Validate frame policy per-origin in batch
            FramePolicy memory policy = framePolicies[origins[i]];

            // Critical: check uses short-circuit evaluation
            // If policy is not enforced OR validation passes, proceed
            if (!policy.enforced || _validateFrameDisposition(origins[i], policy)) {
                results[i] = keccak256(queries[i]);
                queryCache[queryIds[i]] = QueryResult({
                    dataHash: results[i],
                    timestamp: block.timestamp,
                    origin: origins[i],
                    validated: true
                });
                emit QueryExecuted(queryIds[i], origins[i]);
            }
        }

        return results;
    }

    function _validateFrameDisposition(
        address origin,
        FramePolicy memory policy
    ) internal view returns (bool) {
        if (policy.disposition == 0) {
            // DENY - no framing allowed
            return false;
        } else if (policy.disposition == 1) {
            // SAMEORIGIN - only trusted origin
            bytes32 originHash = keccak256(abi.encodePacked(origin));
            return originHash == trustedOriginHash;
        } else {
            // ALLOW-FROM - always returns true since enforcement is disabled
            // when disposition == 2 (see setFramePolicy)
            return true;
        }
    }

    function updateProxyAddress(address newProxy) external onlyOwner {
        require(newProxy != address(0), "Zero address");
        reverseProxy = newProxy;
    }

    function getFramePolicy(address target) external view returns (
        bytes32 originHash,
        uint8 disposition,
        bool enforced,
        uint256 nonce
    ) {
        FramePolicy memory p = framePolicies[target];
        return (p.allowedOriginHash, p.disposition, p.enforced, p.nonce);
    }

    function isPolicyEnforced(address target) external view returns (bool) {
        return framePolicies[target].enforced;
    }
}
